SET statement_timeout = 0;
SET client_encoding = 'UTF8';
SELECT pg_catalog.set_config('search_path', '', false);

CREATE SCHEMA billing;
CREATE TYPE public.order_status AS ENUM ('new', 'paid', 'shipped');

CREATE TABLE public.customers (
    id integer NOT NULL,
    email character varying(255) NOT NULL,
    tags text[],
    meta jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    seen_at timestamp(3) with time zone
);

CREATE SEQUENCE public.customers_id_seq AS integer START WITH 1 INCREMENT BY 1 NO MINVALUE NO MAXVALUE CACHE 1;
ALTER SEQUENCE public.customers_id_seq OWNED BY public.customers.id;
ALTER TABLE ONLY public.customers ALTER COLUMN id SET DEFAULT nextval('public.customers_id_seq'::regclass);

CREATE TABLE billing.invoices (
    id bigint GENERATED BY DEFAULT AS IDENTITY,
    customer_id integer NOT NULL,
    status public.order_status DEFAULT 'new'::public.order_status NOT NULL,
    total numeric(10,2) DEFAULT 0 NOT NULL,
    note text
);

CREATE TABLE public.lines (
    invoice_id bigint NOT NULL,
    n smallint NOT NULL,
    sku character(8) NOT NULL,
    qty integer DEFAULT 1 NOT NULL
);

COMMENT ON TABLE billing.invoices IS 'Issued invoices';
COMMENT ON COLUMN billing.invoices.total IS 'Gross, incl. VAT';

COPY public.customers (id, email) FROM stdin;
1	a@b.c
\.

ALTER TABLE ONLY public.customers ADD CONSTRAINT customers_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.customers ADD CONSTRAINT customers_email_key UNIQUE (email);
ALTER TABLE ONLY billing.invoices ADD CONSTRAINT invoices_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.lines ADD CONSTRAINT lines_pkey PRIMARY KEY (invoice_id, n);
CREATE INDEX invoices_customer_idx ON billing.invoices USING btree (customer_id, status);
CREATE UNIQUE INDEX lines_sku_idx ON public.lines USING hash (sku);
ALTER TABLE ONLY billing.invoices
    ADD CONSTRAINT invoices_customer_fk FOREIGN KEY (customer_id) REFERENCES public.customers(id) ON UPDATE CASCADE ON DELETE RESTRICT;
ALTER TABLE ONLY public.lines
    ADD CONSTRAINT lines_invoice_fk FOREIGN KEY (invoice_id) REFERENCES billing.invoices(id) ON DELETE CASCADE;
